arguments.command:
cd /tmp/vally-eval-trial-KxZpKo && cat > src/CheckoutPricing.Domain/CustomerTier.cs <<'E'
namespace CheckoutPricing.Domain;

public enum CustomerTier
{
    Standard,
    Gold,
}
E
cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class Checkout
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal orderSubtotal) => orderSubtotal;
}
E
cat > tests/CheckoutPricing.IntegrationTests/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.IntegrationTests;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_receives_the_approved_discount()
    {
        var total = new Checkout().CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests 2>&1 | tail -25

